CREATE DATABASE IF NOT EXISTS tripmate_ai CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tripmate_ai;

CREATE TABLE roles (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL UNIQUE, description VARCHAR(500), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, phone_number VARCHAR(30), profile_image VARCHAR(2048), is_verified BOOLEAN NOT NULL DEFAULT FALSE, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, INDEX idx_users_email(email), INDEX idx_users_verified(is_verified));
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE destinations (id BIGINT AUTO_INCREMENT PRIMARY KEY, city VARCHAR(120) NOT NULL, state VARCHAR(120), country VARCHAR(120) NOT NULL, description TEXT, image_url VARCHAR(2048), best_season VARCHAR(100), average_budget DECIMAL(12,2), latitude DECIMAL(10,7), longitude DECIMAL(10,7), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, INDEX idx_destinations_country_city(country,city));
CREATE TABLE trips (id BIGINT AUTO_INCREMENT PRIMARY KEY, trip_name VARCHAR(200) NOT NULL, user_id BIGINT NOT NULL, destination_id BIGINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, budget DECIMAL(12,2) NOT NULL, number_of_travelers INT NOT NULL, trip_status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, CONSTRAINT chk_trips_dates CHECK(end_date>=start_date), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(destination_id) REFERENCES destinations(id), INDEX idx_trips_user_status(user_id,trip_status), INDEX idx_trips_destination_dates(destination_id,start_date,end_date));
CREATE TABLE trip_preferences (trip_id BIGINT NOT NULL, preference VARCHAR(30) NOT NULL, PRIMARY KEY(trip_id,preference), FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE);
CREATE TABLE itineraries (id BIGINT AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT NOT NULL, day_number INT NOT NULL, title VARCHAR(300), description TEXT, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, UNIQUE(trip_id,day_number), FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE, INDEX idx_itinerary_trip_day(trip_id,day_number));
CREATE TABLE activities (id BIGINT AUTO_INCREMENT PRIMARY KEY, itinerary_id BIGINT NOT NULL, title VARCHAR(200) NOT NULL, description TEXT, type VARCHAR(30) NOT NULL, sort_order INT NOT NULL, start_time TIME, end_time TIME, estimated_cost DECIMAL(12,2), location VARCHAR(255), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, UNIQUE(itinerary_id,sort_order), FOREIGN KEY(itinerary_id) REFERENCES itineraries(id) ON DELETE CASCADE, INDEX idx_activities_itinerary(itinerary_id));
CREATE TABLE hotels (id BIGINT AUTO_INCREMENT PRIMARY KEY, destination_id BIGINT NOT NULL, name VARCHAR(200) NOT NULL, address VARCHAR(255), rating DECIMAL(12,2), price_per_night DECIMAL(12,2), image_url VARCHAR(2048), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(destination_id) REFERENCES destinations(id), INDEX idx_hotels_destination(destination_id));
CREATE TABLE restaurants (id BIGINT AUTO_INCREMENT PRIMARY KEY, destination_id BIGINT NOT NULL, name VARCHAR(200) NOT NULL, cuisine VARCHAR(120), address VARCHAR(255), rating DECIMAL(12,2), image_url VARCHAR(2048), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(destination_id) REFERENCES destinations(id), INDEX idx_restaurants_destination(destination_id));
CREATE TABLE attractions (id BIGINT AUTO_INCREMENT PRIMARY KEY, destination_id BIGINT NOT NULL, name VARCHAR(200) NOT NULL, description TEXT, address VARCHAR(255), rating DECIMAL(12,2), entry_fee DECIMAL(12,2), image_url VARCHAR(2048), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(destination_id) REFERENCES destinations(id), INDEX idx_attractions_destination(destination_id));
CREATE TABLE budgets (id BIGINT AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT NOT NULL UNIQUE, total_budget DECIMAL(12,2) NOT NULL, allocated_amount DECIMAL(12,2), spent_amount DECIMAL(12,2), currency CHAR(3) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE);
CREATE TABLE expense_categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, category_type VARCHAR(30) NOT NULL, name VARCHAR(100) NOT NULL, color VARCHAR(7), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, UNIQUE(user_id,category_type), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE expenses (id BIGINT AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT NOT NULL, user_id BIGINT NOT NULL, category_id BIGINT, title VARCHAR(200) NOT NULL, amount DECIMAL(12,2) NOT NULL, expense_date DATE NOT NULL, status VARCHAR(20) NOT NULL, receipt_url VARCHAR(2048), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(trip_id) REFERENCES trips(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES expense_categories(id), INDEX idx_expenses_trip_date(trip_id,expense_date));
CREATE TABLE travel_groups (id BIGINT AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE, INDEX idx_groups_trip(trip_id));
CREATE TABLE group_members (id BIGINT AUTO_INCREMENT PRIMARY KEY, group_id BIGINT NOT NULL, user_id BIGINT NOT NULL, active BOOLEAN NOT NULL, member_role VARCHAR(30), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, UNIQUE(group_id,user_id), FOREIGN KEY(group_id) REFERENCES travel_groups(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE group_expenses (id BIGINT AUTO_INCREMENT PRIMARY KEY, group_id BIGINT NOT NULL, paid_by_member_id BIGINT NOT NULL, description VARCHAR(200) NOT NULL, amount DECIMAL(12,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(group_id) REFERENCES travel_groups(id), FOREIGN KEY(paid_by_member_id) REFERENCES group_members(id), INDEX idx_group_expenses_group(group_id));
CREATE TABLE group_expense_shares (id BIGINT AUTO_INCREMENT PRIMARY KEY, group_expense_id BIGINT NOT NULL, group_member_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL, settled BOOLEAN NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, UNIQUE(group_expense_id,group_member_id), FOREIGN KEY(group_expense_id) REFERENCES group_expenses(id) ON DELETE CASCADE, FOREIGN KEY(group_member_id) REFERENCES group_members(id));
CREATE TABLE saved_trips (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, trip_id BIGINT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, UNIQUE(user_id,trip_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(trip_id) REFERENCES trips(id), INDEX idx_saved_trips_trip(trip_id));
CREATE TABLE packing_checklists (id BIGINT AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT NOT NULL, user_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, UNIQUE(trip_id,user_id), FOREIGN KEY(trip_id) REFERENCES trips(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE packing_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, checklist_id BIGINT NOT NULL, name VARCHAR(200) NOT NULL, quantity INT NOT NULL, packed BOOLEAN NOT NULL, category VARCHAR(100), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, UNIQUE(checklist_id,name), FOREIGN KEY(checklist_id) REFERENCES packing_checklists(id) ON DELETE CASCADE);
CREATE TABLE travel_journals (id BIGINT AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT NOT NULL, user_id BIGINT NOT NULL, journal_date DATE NOT NULL, title VARCHAR(250) NOT NULL, content TEXT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(trip_id) REFERENCES trips(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_journal_trip_date(trip_id,journal_date));
CREATE TABLE journal_photos (id BIGINT AUTO_INCREMENT PRIMARY KEY, journal_id BIGINT NOT NULL, image_url VARCHAR(2048) NOT NULL, caption VARCHAR(500), sort_order INT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(journal_id) REFERENCES travel_journals(id) ON DELETE CASCADE, INDEX idx_journal_photos_journal(journal_id));
CREATE TABLE bookings (id BIGINT AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT NOT NULL, user_id BIGINT NOT NULL, type VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, provider VARCHAR(200) NOT NULL, booking_reference VARCHAR(100) UNIQUE, start_at DATETIME(6), end_at DATETIME(6), amount DECIMAL(12,2), currency CHAR(3), document_url VARCHAR(2048), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(trip_id) REFERENCES trips(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_bookings_trip(trip_id), INDEX idx_bookings_status(status));
CREATE TABLE nearby_places (id BIGINT AUTO_INCREMENT PRIMARY KEY, destination_id BIGINT NOT NULL, name VARCHAR(200) NOT NULL, category VARCHAR(100), address VARCHAR(255), latitude DECIMAL(10,7), longitude DECIMAL(10,7), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(destination_id) REFERENCES destinations(id), INDEX idx_nearby_places_destination(destination_id));
CREATE TABLE favorites (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, destination_id BIGINT, hotel_id BIGINT, restaurant_id BIGINT, attraction_id BIGINT, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(destination_id) REFERENCES destinations(id), FOREIGN KEY(hotel_id) REFERENCES hotels(id), FOREIGN KEY(restaurant_id) REFERENCES restaurants(id), FOREIGN KEY(attraction_id) REFERENCES attractions(id), UNIQUE(user_id,destination_id), UNIQUE(user_id,hotel_id), UNIQUE(user_id,restaurant_id), UNIQUE(user_id,attraction_id));
CREATE TABLE reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, review_type VARCHAR(30) NOT NULL, rating INT NOT NULL, comment TEXT, destination_id BIGINT, hotel_id BIGINT, restaurant_id BIGINT, attraction_id BIGINT, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(destination_id) REFERENCES destinations(id), FOREIGN KEY(hotel_id) REFERENCES hotels(id), FOREIGN KEY(restaurant_id) REFERENCES restaurants(id), FOREIGN KEY(attraction_id) REFERENCES attractions(id), INDEX idx_reviews_user(user_id), INDEX idx_reviews_type(review_type));
CREATE TABLE chat_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, trip_id BIGINT, prompt TEXT NOT NULL, response TEXT NOT NULL, model VARCHAR(100), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(trip_id) REFERENCES trips(id), INDEX idx_chat_user_created(user_id,created_at), INDEX idx_chat_trip(trip_id));
CREATE TABLE analytics (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, metric_name VARCHAR(100) NOT NULL, metric_date DATE NOT NULL, payload JSON, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE(user_id,metric_name,metric_date), INDEX idx_analytics_metric_date(metric_name,metric_date));
CREATE TABLE notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, notification_type VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, is_read BOOLEAN NOT NULL, read_at DATETIME(6), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_notifications_user_read(user_id,is_read), INDEX idx_notifications_type(notification_type));
CREATE TABLE admin_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT NOT NULL, action VARCHAR(100) NOT NULL, target_type VARCHAR(100), target_id BIGINT, details TEXT, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(admin_id) REFERENCES users(id), INDEX idx_admin_logs_admin_created(admin_id,created_at), INDEX idx_admin_logs_action(action));
CREATE TABLE refresh_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, token VARCHAR(512) NOT NULL UNIQUE, expires_at DATETIME(6) NOT NULL, revoked BOOLEAN NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_refresh_tokens_user(user_id));
CREATE TABLE password_reset_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, token VARCHAR(512) NOT NULL UNIQUE, expires_at DATETIME(6) NOT NULL, used_at DATETIME(6), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by BIGINT, FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_password_reset_user(user_id));
